const std = @import("std");

fn countPositive(values: []const i32) u32 {
    var count: u32 = 0;
    for (values) |value| {
        if (value > 0) {
            count += 1;
        }
    }
    return count;
}

pub fn main() void {
    const values = [_]i32{ 3, -1, 2 };
    std.debug.print("{d}\n", .{countPositive(values[0..])});
}
